
"""Kaggriculture v20_1, try to make improvement on forecast(obs) to check the performance
"""
import math
import base64
import struct

# Crop tuple format: (seed_cost, reference/base market price, yield_schedule, final_yield_age).
# yield_schedule contains (crop_age_in_days, units_produced) events; e.g. WHEAT
# costs 10, has reference price 25, yields 4 units at age 4, and its last yield is age 4.
CROPS={
 'WHEAT':(10,25,((4,4),),4),
 'CARROT':(20,35,((3,3),),3),
 'TOMATO':(50,60,((8,2),(9,2),(10,2),(11,2)),11),
 'STRAWBERRY':(100,120,((10,2),(12,2),(14,2),(16,2)),16),
 'MELON':(80,250,((10,6),),10)}
ANIMALS={'COW':(400,'MILK',8,2,3),'SHEEP':(500,'WOOL',6,3,4),'GOOSE':(300,'EGG',4,1,2)}

# Per-shop demand on each town consumption tick.
# Values are {product: units_consumed}. Single-product shops consume 2x.
SHOPS={
 'BAKERY':{'WHEAT':1,'EGG':1},
 'PIZZA_SHOP':{'MILK':1,'TOMATO':1,'WHEAT':1},
 'BRUNCH_SPOT':{'EGG':1,'WHEAT':1,'STRAWBERRY':1},
 'YARN_STORE':{'WOOL':2},
 'ICE_CREAM_SHOP':{'STRAWBERRY':1,'MILK':1,'WHEAT':1},
 'PET_CAFE':{'CARROT':2},
 'SMOOTHIE_SHOP':{'STRAWBERRY':1,'MILK':1},
 'FARMERS_MARKET':{'WHEAT':1,'CARROT':1,'TOMATO':1,'STRAWBERRY':1}}

ROUTES=(((4,4),(4,3),(4,2)),((3,4),(3,3),(2,3)),((5,4),(5,3)),((6,4),(6,3)),((4,5),(3,5)),((4,6),(3,6)))
ANIMAL_POINTS={p for route in ROUTES for p in route}
# The shed occupies the central 2x2 tiles. These coordinates are the transfer interface
# used for PICKUP/DROP/PLACE decisions and as routing targets via nearest_shed().
SHED=((4,4),(5,4),(4,5),(5,5))
PASS=['PASS']
# Maximum size of the desired animal plan. animal_plan() stops adding new animals once
# existing/planned animals fill 13 route slots.
HERD_LIMIT=13
FERT_FACTOR=0.8
# Heuristic daily labor/maintenance penalty used only when animal_plan() estimates
# the economics of adding an animal. It is not a fee charged by the game engine.
LABOR_COST=20
# Minimum projected net score required for animal_plan() to expand the herd. If the
# best candidate animal is below 200, planning stops adding animals.
HERD_THRESHOLD=200
OPP_STYLE=None
# Legacy opponent-style tuning tuple. In this v20 file it is never read, so its values
# have no runtime effect and the tuple-component semantics cannot be recovered from v20.
TRADER_MIX=(6,4,5)
# Legacy opponent-style tuning tuple; defined but unused in v20, so changing it does
# not change the policy.
NORMAL_MIX=(8,5,0)
# Legacy V16-specific tuning tuple; defined but never consumed in v20. Active V16
# behavior instead comes from OPP_STYLE, V16_FINAL_HANDS, V16_FINAL_BONUS, and seed ordering.
V16_MIX=(7,4,0)
V16_FINAL_HANDS=10
V16_FINAL_BONUS=160

# Global game-clock constants for the 30-day, 24-turn/day season.
TURNS_PER_DAY=24
SEASON_TURNS=720
SHOP_INTERVAL=4
CENTER_INTERVAL=24
SHOP_UNLOCK_TURNS=3*TURNS_PER_DAY
MAX_SHOPS=8

# Absolute turn counter for this agent instance. agent(obs) resets it at the
# opening observation and advances it once after every call.
STEP=0

def price(item, inventory):
    # Heuristic market-price model used by the crop/animal planners. Inventory 10,000 is
    # treated as the equilibrium point (d == 0). Scarcity (d < 0) raises the estimate;
    # surplus (d >= 0) lowers it with item-specific curves, always floored at 1. The
    # function forecasts planning value from projected inventory; it does not read the
    # live market price directly.
    d=inventory-10000
    if item=='WHEAT':return max(1,25-5*math.log1p(d)/math.log(401)) if d>=0 else 25+math.sqrt(-d)
    if item in ('CARROT','TOMATO','EGG'):
        base,through,up,down={'CARROT':(35,450,1,.7),'TOMATO':(60,200,.4,.6),'EGG':(50,332,.4,.2)}[item]
        u=abs(d)/through
        if d<0:return base*(1+up*(u+8*max(0,u-1)**2))
        return max(1,base*(1-down*math.sqrt(u))) if item!='EGG' else max(1,base-10*math.log1p(d)/math.log(333))
    if item=='STRAWBERRY':return max(1,120-1.92*d) if d>=0 else 120+8.4*math.sqrt(-d)
    if item=='MELON':return max(1,250-.01*d*d) if d>=0 else 250+50*math.log1p(-d)/math.log(301)
    if item=='MILK':return max(1,160-256*d/122) if d>=0 else 160+96*math.sqrt(-d/122)
    if item=='WOOL':return max(1,200-640*(d/105)**2) if d>=0 else 200+40*math.log1p(-d)/math.log(106)
    return max(1,100-.2*d)

# Manhattan grid distance. It is used for route ordering, nearest-shed selection,
# worker/task travel cost, deadlines, and feasibility checks.
def dist(a,b):return abs(a[0]-b[0])+abs(a[1]-b[1])
def move(a,b):
    # Return one cardinal step from a toward b. Prefer the x-axis when |dx| >= |dy|;
    # otherwise move on y. If already at b, PASS.
    dx=b[0]-a[0];dy=b[1]-a[1]
    if abs(dx)>=abs(dy) and dx:return ['EAST' if dx>0 else 'WEST']
    if dy:return ['SOUTH' if dy>0 else 'NORTH']
    return PASS
def nearest_shed(p):return min(SHED,key=lambda s:dist(p,s))
# Convert an (x, y) farm coordinate to the row-major tile grid entry tiles[y][x].
def tile(f,p):return f['tiles'][p[1]][p[0]]
def totals(private):
    # Aggregate the player's private shed inventory plus every farmer/hand inventory into
    # one item-count dictionary. Seeds and items already placed on farm tiles are separate.
    result=dict(private['shed'])
    for inv in private['inventories']:
        for c,n in inv.items():result[c]=result.get(c,0)+n
    return result

def forecast(obs):
    # Hour-aware market forecast over all 720 turns.
    #
    # net_flow[item][t] is the estimated change to shared market inventory during
    # absolute turn t: positive values add market supply, negative values consume it.
    # projected[item][t] is the estimated market inventory at the START of turn t,
    # before that turn's market orders and town consumption. This matches engine order:
    # player market orders execute first, then town/shop demand for the same step.
    #
    # This first hourly version intentionally keeps the old production assumptions
    # coarse, but places them on the real turn timeline. Future work can improve the
    # sell-delay/opponent models without changing the 720-turn forecast interface.
    global STEP
    day=obs['day'];hour=obs['hour'];step=STEP
    items=obs['market']['inventory'];shops=obs['town']['unlocked_shops']

    net_flow={c:[0.]*SEASON_TURNS for c in items}
    projected={c:[float(items[c])]*SEASON_TURNS for c in items}

    # Exact demand from currently unlocked shops. Duplicate shop names in shops
    # are counted independently, and SHOPS stores the per-product quantity explicitly.
    current_shop_demand={c:0. for c in items}
    for shop in shops:
        for c,n in SHOPS[shop].items():
            if c in current_shop_demand:current_shop_demand[c]+=n

    # Expected demand contribution of one future random shop instance per shop tick.
    # Unlocks are drawn uniformly with replacement from the eight shop types.
    expected_shop_demand={c:0. for c in items}
    for products in SHOPS.values():
        for c,n in products.items():
            if c in expected_shop_demand:expected_shop_demand[c]+=n/len(SHOPS)

    # Shops unlock at the start of days 3,6,9,... after the preceding end-of-day
    # refresh. Existing shops already includes unlocks visible at the current step.
    future_slots=max(0,MAX_SHOPS-len(shops))
    first_unlock=((step//SHOP_UNLOCK_TURNS)+1)*SHOP_UNLOCK_TURNS
    future_unlocks=list(range(first_unlock,SEASON_TURNS,SHOP_UNLOCK_TURNS))[:future_slots]
    unlock_i=0;expected_new_shops=0.
    for t in range(step,SEASON_TURNS):
        while unlock_i<len(future_unlocks) and future_unlocks[unlock_i]<=t:
            expected_new_shops+=1.;unlock_i+=1
        if t%SHOP_INTERVAL==0:
            for c in items:
                net_flow[c][t]-=current_shop_demand[c]+expected_new_shops*expected_shop_demand[c]
        if t%CENTER_INTERVAL==0:
            for c in items:
                if c!='FERTILIZER':net_flow[c][t]-=1.

    # Future supply is rebuilt from the latest observation every turn.
    # Our side models when existing goods/assets are expected to reach the market:
    #   1) shed stock -> immediate supply;
    #   2) carried stock -> supply after delivery to the shed;
    #   3) yield already sitting on our tiles -> harvest + delivery;
    #   4) remaining output of crops currently planted;
    #   5) recurring output of animals currently placed, assuming they are well cared.
    # We deliberately do NOT forecast replacement crops after a current crop finishes;
    # a newly planted crop enters the forecast only after it appears in a later observation.
    player=obs['player'];private=obs['private'];own_farm=obs['farms'][player]
    shed=private['shed'];total=totals(private)
    positions=[tuple(own_farm['farmer'])]+[tuple(p) for p in own_farm['hands']]

    # Keep the existing opponent-visible-production heuristic separate from our improved
    # own-side future supply model. Opponent hidden inventory/replanting remains uncertain.
    herd=0
    for farm in obs['farms']:
        for row in farm['tiles']:
            for tile_state in row:
                if isinstance(tile_state,dict) and 'animal' in tile_state:herd+=1
    opp_farm=obs['farms'][1-player]
    for row in opp_farm['tiles']:
        for tile_state in row:
            if not isinstance(tile_state,dict):continue
            if 'animal' in tile_state:
                a=ANIMALS[tile_state['animal']];product=a[1]
                held=tile_state.get('yield_units',0)
                if held:net_flow[product][step]+=held
                first_day=tile_state['placed_day']+a[2]
                for at_day in range(max(day+1,first_day),30):
                    if (at_day-first_day)%a[3]==0:
                        net_flow[product][at_day*TURNS_PER_DAY]+=a[4]
            if 'crop' not in tile_state:continue
            c=tile_state['crop'];planted=tile_state['planted_day'];ongoing=c in ('TOMATO','STRAWBERRY')
            held=tile_state.get('yield_units',0) if ongoing or day>=planted+CROPS[c][3] else 0
            if held:net_flow[c][step]+=held
            for age,units in CROPS[c][2]:
                at_day=planted+age;at_turn=at_day*TURNS_PER_DAY
                if at_turn>step and at_day<30:
                    net_flow[c][at_turn]+=1.8 if ongoing else units

    # Reserve policy mirrors market_orders(). Allocate today's sellable budget to shed
    # stock first, then to carried stock as it reaches the shed.
    live=sum(
        1 for row in own_farm['tiles'] for tile_state in row
        if isinstance(tile_state,dict) and 'animal' in tile_state
    )
    reserve_wheat=0 if day==29 else max(4,live+2)
    reserve_fert=0 if day<10 or day==29 else 4
    sellable_budget={c:total.get(c,0) for c in net_flow}
    if 'WHEAT' in sellable_budget:sellable_budget['WHEAT']=max(0,total.get('WHEAT',0)-reserve_wheat)
    if 'FERTILIZER' in sellable_budget:sellable_budget['FERTILIZER']=max(0,total.get('FERTILIZER',0)-reserve_fert)

    # Immediate supply: goods already in the shed can be sold this turn.
    for c,n in shed.items():
        if c not in net_flow or n<=0:continue
        sellable=min(n,sellable_budget.get(c,0))
        if sellable:
            net_flow[c][step]+=sellable
            sellable_budget[c]-=sellable

    # Carried goods are future supply. Estimate the earliest shed arrival from the
    # worker's current position; automatic end-of-day drop provides an upper bound.
    next_day_turn=(day+1)*TURNS_PER_DAY
    for i,inv in enumerate(private['inventories']):
        if i>=len(positions):break
        pos=positions[i]
        travel_turn=step+max(1,dist(pos,nearest_shed(pos)))
        delivery_turn=min(travel_turn,next_day_turn) if day<29 else travel_turn
        if delivery_turn>=SEASON_TURNS:continue
        for c,n in inv.items():
            if c not in net_flow or n<=0:continue
            sellable=min(n,sellable_budget.get(c,0))
            if sellable:
                net_flow[c][delivery_turn]+=sellable
                sellable_budget[c]-=sellable

    # Tile stock needs HARVEST plus transport to a shed-access tile. For yield already
    # visible now, include the nearest current worker's approach distance. For future
    # production we assume a worker can be present at the tile when production lands.
    def own_market_turn(p,ready_turn,include_worker_approach=False):
        approach=min(dist(pos,p) for pos in positions) if include_worker_approach and positions else 0
        return ready_turn+approach+dist(p,nearest_shed(p))+1

    for y,row in enumerate(own_farm['tiles']):
        for x,tile_state in enumerate(row):
            if not isinstance(tile_state,dict):continue
            p=(x,y)

            if 'animal' in tile_state:
                a=ANIMALS[tile_state['animal']]
                product=a[1];held=tile_state.get('yield_units',0)
                if held:
                    at=own_market_turn(p,step,True)
                    if at<SEASON_TURNS:net_flow[product][at]+=held

                # Existing animals are forecast for the rest of the season. Under the
                # well-cared assumption, use v20's steady-state 3/4/2 units per event.
                first_day=tile_state['placed_day']+a[2]
                for at_day in range(max(day+1,first_day),30):
                    if (at_day-first_day)%a[3]:continue
                    ready_turn=at_day*TURNS_PER_DAY
                    at=own_market_turn(p,ready_turn)
                    if at<SEASON_TURNS:net_flow[product][at]+=a[4]

            if 'crop' not in tile_state:continue
            crop=tile_state['crop'];planted=tile_state['planted_day']
            ongoing=crop in ('TOMATO','STRAWBERRY')
            held=tile_state.get('yield_units',0)
            if held:
                at=own_market_turn(p,step,True)
                if at<SEASON_TURNS:net_flow[crop][at]+=held

            # Forecast only the remaining output of the crop currently on this tile.
            # No replacement crop is assumed after its last scheduled harvest.
            for age,scheduled_units in CROPS[crop][2]:
                at_day=planted+age;ready_turn=at_day*TURNS_PER_DAY
                if ready_turn<=step or at_day>=30:continue
                if ongoing:
                    # Base scheduled yield is 1; current fertilizer coverage makes it 2
                    # assuming the crop is watered. Later fertilization is learned from
                    # later observations and the rolling forecast is rebuilt then.
                    units=2 if tile_state.get('fertilized_until_day',-1)>=at_day else 1
                else:
                    # One-time crop schedule is a final total, so subtract any yield
                    # already visible on the tile to avoid counting it twice.
                    units=max(0,scheduled_units-held)
                if not units:continue
                at=own_market_turn(p,ready_turn)
                if at<SEASON_TURNS:net_flow[crop][at]+=units

    # Retain the old herd-to-wheat-demand heuristic, but express it as one daily flow
    # rather than subtracting a fractional amount continuously across a day.
    if 'WHEAT' in net_flow and herd:
        first_feed=((step//TURNS_PER_DAY)+1)*TURNS_PER_DAY
        for t in range(first_feed,SEASON_TURNS,TURNS_PER_DAY):
            net_flow['WHEAT'][t]-=herd

    # Convert per-turn net flow into expected start-of-turn market inventory.
    for c in items:
        running=float(items[c])
        for t in range(step,SEASON_TURNS):
            projected[c][t]=running
            running+=net_flow[c][t]
    daily_projected={
        c:[projected[c][min(SEASON_TURNS-1,d*TURNS_PER_DAY)] for d in range(31)]
        for c in projected
    }
    return daily_projected,net_flow

def animal_plan(obs,projected):
    # Produce a desired {tile: animal_type} layout on the fixed animal ROUTES.
    # Logic: keep already-placed route animals, allocate owned-but-unplaced animals to free
    # route slots, then on days 3..17 consider additional animals. Each species is scored
    # by projected product revenue + fertilizer value - wheat feed - LABOR_COST - purchase
    # cost. Expansion is capped by HERD_LIMIT and stops below HERD_THRESHOLD. A local copy
    # of projected inventory is updated after each choice to model its future supply impact.
    f=obs['farms'][obs['player']];day=obs['day'];plan={}
    for row in ROUTES:
        for p in row:
            t=tile(f,p)
            if isinstance(t,dict) and t.get('animal'):plan[p]=t['animal']
    slots=sorted(ANIMAL_POINTS,key=lambda p:(dist(p,nearest_shed(p)),p))
    stock=totals(obs['private'])
    for a in ANIMALS:
        for _ in range(stock.get(a,0)):
            p=next((p for p in slots if p not in plan and tile(f,p)!='LOCKED'),None)
            if p is not None:plan[p]=a
    if day<3 or day>17:return plan
    projected={c:list(v) for c,v in projected.items()}
    for p in slots:
        if p in plan or tile(f,p)=='LOCKED':continue
        if len(plan)>=HERD_LIMIT:break
        scores=[]
        start=day+1
        for a,(cost,product,first,interval,units) in ANIMALS.items():
            events=list(range(start+first,30,interval))
            income=sum(units*price(product,projected[product][d]+units/2) for d in events)
            income+=sum(FERT_FACTOR*price('FERTILIZER',projected['FERTILIZER'][d])-price('WHEAT',projected['WHEAT'][d])-LABOR_COST for d in range(start,29))
            scores.append((income-cost,a,events,product,units))
        score,a,events,product,units=max(scores)
        if score<HERD_THRESHOLD:break
        plan[p]=a
        for d in events:
            for at in range(d,31):projected[product][at]+=units
        for at in range(start,31):projected['FERTILIZER'][at]+=(at-start)*FERT_FACTOR
    return plan

def crop_plan(obs,projected,animal):
    # Produce a desired {tile: crop_type} layout for unlocked tiles outside ANIMAL_POINTS.
    # Existing crops are preserved. Days 0..3 use a fixed 13-WHEAT/6-MELON opening; later
    # candidates are scored from projected future sale value - seed/fertilizer cost,
    # normalized by production duration and adjusted by crop-specific heuristic multipliers.
    # Owned seeds receive a small bonus, and projected supply is updated after each choice.
    # Note: the `animal` argument is currently unused; exclusion uses fixed ANIMAL_POINTS.
    f=obs['farms'][obs['player']];day=obs['day'];seeds=obs['private']['seeds'];plan={}
    points=[(x,y) for y in range(10) for x in range(10) if tile(f,(x,y))!='LOCKED' and (x,y) not in ANIMAL_POINTS]
    points.sort(key=lambda p:(dist(p,nearest_shed(p)),p[1],p[0]))
    # Preserve a cheap productive opening before switching to the market forecast.
    opening=[p for p in points if p[0]<5 and p[1]<5]
    opening.sort(key=lambda p:(p[1],p[0]))
    wheat=set(opening[:13]);melon=set(opening[13:19])
    for p in points:
        t=tile(f,p)
        if isinstance(t,dict) and 'crop' in t:plan[p]=t['crop'];continue
        if isinstance(t,dict) and t.get('kind') not in ('WEED',):continue
        if day<=3 and p in wheat|melon:
            c='WHEAT' if p in wheat else 'MELON'
        else:
            scores=[]
            for c,(cost,base,events,last) in CROPS.items():
                future=[(day+age,n) for age,n in events if day+age<=29]
                if not future:continue
                fert=(len(future)*.65*price('FERTILIZER',projected['FERTILIZER'][min(29,day+8)])) if c in ('STRAWBERRY','TOMATO') else 0
                rev=sum(n*price(c,projected[c][at]+n/2) for at,n in future)-cost-fert
                duration=future[-1][0]-day+1
                score=rev/duration
                if c=='STRAWBERRY':score*=1.6
                elif c=='TOMATO':score*=0.6
                elif c=='WHEAT':score*=2
                if day<4 and c=='WHEAT':score*=1.7
                if seeds.get(c,0)>0:score+=cost/duration*.6
                scores.append((score,c))
            if not scores:continue
            c=max(scores)[1]
        plan[p]=c
        for age,n in CROPS[c][2]:
            at=day+age
            for future in range(at,31):projected[c][future]+=n
    return plan

def fert_value(t,day,prices):
    # Approximate the marginal value of fertilizing a crop now. Only TOMATO/STRAWBERRY are
    # considered. Already-covered crops return 0. Otherwise it looks for yield events in
    # the next three crop-age steps, requires an event on the next step, and returns
    # current_crop_price * number_of_covered_events - fertilizer_price. unit_actions() uses
    # this to create FERTILIZE tasks; market_orders() uses it to size fertilizer purchases.
    if t.get('fertilized_until_day',-1)>=day:return 0
    c=t['crop'];age=day-t['planted_day']
    if c in ('TOMATO','STRAWBERRY'):
        first=8 if c=='TOMATO' else 10;interval=1 if c=='TOMATO' else 2
        covered=[a for a,n in CROPS[c][2] if age<a<=age+3 and day+a-age<=29]
        if age+1 not in covered:return 0
        return prices[c]*len(covered)-prices['FERTILIZER']
